import { test, expect } from '@playwright/test';

test.describe('Login Form Validation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://www.saucedemo.com');
  });

  test('should display error when both username and password fields are empty', async ({ page }) => {
    // Verify login button is visible
    const loginButton = page.getByRole('button', { name: /login/i });
    await expect(loginButton).toBeVisible();

    // Verify error container is not visible initially
    const errorContainer = page.locator('[data-test="error"]');
    await expect(errorContainer).not.toBeVisible();

    // Click login button with empty fields
    await loginButton.click();

    // Verify error container is now visible
    await expect(errorContainer).toBeVisible();

    // Verify error message contains 'Username is required'
    const errorMessage = page.getByText(/Username is required/i);
    await expect(errorMessage).toBeVisible();

    // Verify error message contains 'Password is required'
    const passwordError = page.getByText(/Password is required/i);
    await expect(passwordError).toBeVisible();
  });

  test('should display error when only password field is filled', async ({ page }) => {
    // Fill username field with valid data
    const usernameInput = page.getByLabel(/username/i);
    await usernameInput.fill('standard_user');

    // Verify username field has value
    await expect(usernameInput).toHaveValue('standard_user');

    // Click login button with empty password field
    const loginButton = page.getByRole('button', { name: /login/i });
    await loginButton.click();

    // Verify error container is visible
    const errorContainer = page.locator('[data-test="error"]');
    await expect(errorContainer).toBeVisible();

    // Verify error message contains 'Password is required'
    const passwordError = page.getByText(/Password is required/i);
    await expect(passwordError).toBeVisible();

    // Verify error message does not contain 'Username is required'
    const usernameError = page.getByText(/Username is required/i);
    await expect(usernameError).not.toBeVisible();
  });
});
